use xiom.io;

use xiom.string;
fn parse_value(raw: Str) -> Result[Int, Str] {
  return string.str_to_int(raw);
}

fn double_it(val: Int) -> Result[Int, Str] {
  return Ok(val * 2);
}

fn add_ten(val: Int) -> Result[Int, Str] {
  return Ok(val + 10);
}

fn check_even(val: Int) -> Result[Str, Str] {
  if val % 2 == 0 {
    return Ok("Final value: " + to_string(val) + " (even)");
  }
  else {
    return Err("Final value is not even");
  }
}

fn run_pipeline(raw: Str) -> Result[Str, Str] {
  let v = parse_value(raw)?;
  let doubled = double_it(v)?;
  let offset = add_ten(doubled)?;
  return check_even(offset);
}

fn main() -> Int {
  match run_pipeline("5") {
    Ok(result) => { io.println(result.to_str()); return 200; }
    Err(e) => { io.println(e.to_str()); return 400; }
  }
}
